// Package calendar provides calendar days without time of day or zone.
package calendar

import (
	"errors"
	"fmt"
	"time"
)

// ErrInvalidDate is returned for dates that do not exist or are badly written. (T3)
var ErrInvalidDate = errors.New("calendar: invalid date")

// Date is a single calendar day. (T3)
type Date struct {
	year  int
	month time.Month
	day   int
}

// New builds a Date from its parts. (T3)
func New(year int, month time.Month, day int) (Date, error) {
	if year < 1000 || year > 9999 || month < time.January || month > time.December || day < 1 ||
		day > time.Date(year, month+1, 0, 0, 0, 0, 0, time.UTC).Day() {
		return Date{}, fmt.Errorf("%w: %d-%d-%d", ErrInvalidDate, year, int(month), day)
	}
	return Date{year, month, day}, nil
}

// Parse reads a date in the form YYYY-MM-DD. (T3)
func Parse(s string) (Date, error) {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return Date{}, fmt.Errorf("%w: %q", ErrInvalidDate, s)
	}
	var n [3]int
	for i, part := range []string{s[:4], s[5:7], s[8:]} {
		for _, c := range []byte(part) {
			if c < '0' || c > '9' {
				return Date{}, fmt.Errorf("%w: %q", ErrInvalidDate, s)
			}
			n[i] = n[i]*10 + int(c-'0')
		}
	}
	return New(n[0], time.Month(n[1]), n[2])
}

// String returns the date as YYYY-MM-DD. (T3)
func (d Date) String() string {
	return fmt.Sprintf("%04d-%02d-%02d", d.year, int(d.month), d.day)
}

// AddDays returns the date n calendar days later (earlier if n < 0). (T3)
func (d Date) AddDays(n int) Date {
	t := time.Date(d.year, d.month, d.day+n, 0, 0, 0, 0, time.UTC)
	return Date{t.Year(), t.Month(), t.Day()}
}

// Weekday returns the day of the week. (T3)
func (d Date) Weekday() time.Weekday {
	return d.time().Weekday()
}

// DaysBetween returns the signed number of days from from to to, counting both ends: a day
// to itself is 1, and an earlier to gives the negative of the count from to to from. (T3, as
// corrected)
func DaysBetween(from, to Date) int {
	n := int((to.time().Unix() - from.time().Unix()) / 86400)
	if n < 0 {
		return n - 1
	}
	return n + 1
}

func (d Date) time() time.Time {
	return time.Date(d.year, d.month, d.day, 0, 0, 0, 0, time.UTC)
}

reference.isbn/isbn.go:
// Package isbn validates and normalises book numbers.
package isbn

import (
	"errors"
	"fmt"
	"strings"
)

// ErrInvalidISBN is returned by Parse for text that is not a valid ISBN. (T2)
var ErrInvalidISBN = errors.New("isbn: invalid ISBN")

// ISBN is a validated ISBN-13 held as 13 digits. (T2)
type ISBN string

// Parse accepts an ISBN-10 or ISBN-13 and returns the 13-digit form. (T2)
func Parse(s string) (ISBN, error) {
	t := strings.NewReplacer("-", "", " ", "").Replace(strings.TrimSpace(s))
	switch {
	case len(t) == 13 && digits(t):
		if sum13(t)%10 == 0 {
			return ISBN(t), nil
		}
	case len(t) == 10 && digits(t[:9]) && (digits(t[9:]) || t[9] == 'X' || t[9] == 'x'):
		sum := 0
		for i := 0; i < 10; i++ {
			v := int(t[i] - '0')
			if i == 9 && (t[i] == 'X' || t[i] == 'x') {
				v = 10
			}
			sum += v * (10 - i)
		}
		if sum%11 == 0 {
			body := "978" + t[:9]
			return ISBN(body + string(rune('0'+(10-sum13(body)%10)%10))), nil
		}
	}
	return "", fmt.Errorf("%w: %q", ErrInvalidISBN, s)
}

// sum13 is the ISBN-13 weighted sum of s's digits, weights 1, 3, 1, 3, ... from the left.
func sum13(s string) int {
	sum := 0
	for i := range len(s) {
		sum += int(s[i]-'0') * (1 + 2*(i%2))
	}
	return sum
}

func digits(s string) bool {
	for _, b := range []byte(s) {
		if b < '0' || b > '9' {
			return false
		}
	}
	return true
}

// String returns the 13 digits. (T2)
func (i ISBN) String() string {
	return string(i)
}

reference.lending/fine.go:
package lending

import (
	"fmt"

	"example.com/libloans/calendar"
	"example.com/libloans/money"
)

// Fine returns the late fine for an item returned on returned. (T5)
func Fine(kind ItemKind, due, returned calendar.Date) (money.Cents, error) {
	rate := map[ItemKind][2]money.Cents{Book: {25, 1000}, DVD: {100, 1500}, Magazine: {10, 300}}
	r, ok := rate[kind]
	if !ok {
		return 0, fmt.Errorf("%w: %d", ErrUnknownKind, int(kind))
	}
	// DaysBetween counts both ends (T3 as corrected), so the days late are one fewer.
	late := money.Cents(calendar.DaysBetween(due, returned) - 1)
	if late <= 0 {
		return 0, nil
	}
	return min(late*r[0], r[1]), nil
}

reference.lending/kind.go:
// Package lending holds the library's loan rules.
package lending

import (
	"errors"
	"fmt"
	"strings"
	"time"

	"example.com/libloans/calendar"
)

// ErrUnknownKind is returned for an item kind the library does not lend. (T4)
var ErrUnknownKind = errors.New("lending: unknown item kind")

// ItemKind is the type of item on loan. The zero value is not valid. (T4)
type ItemKind int

// Item kinds. (T4)
const (
	Book ItemKind = iota + 1
	DVD
	Magazine
)

// ParseKind reads "book", "dvd" or "magazine" in any case. (T4)
func ParseKind(s string) (ItemKind, error) {
	for _, k := range []ItemKind{Book, DVD, Magazine} {
		if strings.ToLower(strings.TrimSpace(s)) == k.String() {
			return k, nil
		}
	}
	return 0, fmt.Errorf("%w: %q", ErrUnknownKind, s)
}

// String returns "book", "dvd", "magazine" or "unknown". (T4)
func (k ItemKind) String() string {
	switch k {
	case Book:
		return "book"
	case DVD:
		return "dvd"
	case Magazine:
		return "magazine"
	}
	return "unknown"
}

// period is the kind's loan period in days, or 0 for an invalid kind.
func period(k ItemKind) int {
	return map[ItemKind]int{Book: 21, DVD: 7, Magazine: 14}[k]
}

// DueDate returns the due date for an item of this kind lent on from. (T4)
func DueDate(kind ItemKind, from calendar.Date) (calendar.Date, error) {
	days := period(kind)
	if days == 0 {
		return calendar.Date{}, fmt.Errorf("%w: %d", ErrUnknownKind, int(kind))
	}
	due := from.AddDays(days)
	if due.Weekday() == time.Sunday {
		due = due.AddDays(1)
	}
	return due, nil
}

reference.lending/loan.go:
package lending

import (
	"errors"
	"fmt"
	"strings"

	"example.com/libloans/calendar"
	"example.com/libloans/isbn"
)

// ErrMalformedLine is returned for a loan record that is structurally wrong. (T7)
var ErrMalformedLine = errors.New("lending: malformed loan record")

// Loan is one item lent to one patron. Returned is nil while on loan. (T7)
type Loan struct {
	Patron   string
	ISBN     isbn.ISBN
	Title    string
	Kind     ItemKind
	Borrowed calendar.Date
	Due      calendar.Date
	Returned *calendar.Date
}

// ParseLoan reads one "patron|isbn|title|kind|borrowed|returned" line. (T7)
func ParseLoan(line string) (Loan, error) {
	f := strings.Split(line, "|")
	if len(f) != 6 {
		return Loan{}, fmt.Errorf("%w: %d fields, want 6", ErrMalformedLine, len(f))
	}
	for i := range f {
		f[i] = strings.TrimSpace(f[i])
	}
	if f[0] == "" || f[2] == "" {
		return Loan{}, fmt.Errorf("%w: empty patron or title", ErrMalformedLine)
	}
	l := Loan{Patron: f[0], Title: f[2]}
	var err error
	if l.ISBN, err = isbn.Parse(f[1]); err != nil {
		return Loan{}, err
	}
	if l.Kind, err = ParseKind(f[3]); err != nil {
		return Loan{}, err
	}
	if l.Borrowed, err = calendar.Parse(f[4]); err != nil {
		return Loan{}, err
	}
	if f[5] != "" {
		returned, err := calendar.Parse(f[5])
		if err != nil {
			return Loan{}, err
		}
		if calendar.DaysBetween(l.Borrowed, returned) < 0 {
			return Loan{}, fmt.Errorf("%w: returned %s before borrowed %s", ErrMalformedLine, returned, l.Borrowed)
		}
		l.Returned = &returned
	}
	l.Due, err = DueDate(l.Kind, l.Borrowed)
	return l, err
}

reference.lending/renew.go:
package lending

import (
	"errors"

	"example.com/libloans/calendar"
)

// Renewal errors. (T6)
var (
	ErrAlreadyReturned = errors.New("lending: item already returned")
	ErrNotRenewable    = errors.New("lending: item kind cannot be renewed")
	ErrOnHold          = errors.New("lending: item has a hold pending")
	ErrRenewalLimit    = errors.New("lending: renewal limit reached")
	ErrOverdue         = errors.New("lending: item is overdue")
)

// Renew returns the new due date for a loan renewed on today. (T6)
func Renew(l Loan, today calendar.Date, renewalsSoFar int, holdPending bool) (calendar.Date, error) {
	switch {
	case l.Returned != nil:
		return calendar.Date{}, ErrAlreadyReturned
	case period(l.Kind) == 0:
		return calendar.Date{}, ErrUnknownKind
	case l.Kind == Magazine:
		return calendar.Date{}, ErrNotRenewable
	case holdPending:
		return calendar.Date{}, ErrOnHold
	case renewalsSoFar >= 2:
		return calendar.Date{}, ErrRenewalLimit
	// DaysBetween counts both ends (T3 as corrected): 1 is the due date itself.
	case calendar.DaysBetween(l.Due, today) > 1:
		return calendar.Date{}, ErrOverdue
	}
	next, err := DueDate(l.Kind, today)
	if err != nil {
		return calendar.Date{}, err
	}
	if calendar.DaysBetween(l.Due, next) <= 1 {
		return l.Due, nil
	}
	return next, nil
}

reference.money/money.go:
// Package money holds amounts of money in whole cents.
package money

import (
	"errors"
	"fmt"
	"strings"
)

// ErrInvalidAmount is returned by Parse for text that is not a valid amount. (T1)
var ErrInvalidAmount = errors.New("money: invalid amount")

// Cents is an amount of money in cents. (T1)
type Cents int64

// Parse reads an amount such as "12.50" and returns it in cents. (T1)
func Parse(s string) (Cents, error) {
	whole, frac, dotted := strings.Cut(s, ".")
	if len(whole) < 1 || len(whole) > 9 || !digits(whole) || dotted && (len(frac) != 2 || !digits(frac)) {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	var c Cents
	for _, b := range []byte(whole + frac) {
		c = c*10 + Cents(b-'0')
	}
	if !dotted {
		c *= 100
	}
	return c, nil
}

func digits(s string) bool {
	for _, b := range []byte(s) {
		if b < '0' || b > '9' {
			return false
		}
	}
	return true
}

// String formats the amount as "$12.50" or "-$3.05". (T1)
func (c Cents) String() string {
	sign, u := "", uint64(c)
	if c < 0 {
		// The negation wraps, so the minimum int64 keeps its magnitude.
		sign, u = "-", -u
	}
	return fmt.Sprintf("%s$%d.%02d", sign, u/100, u%100)
}

reference.report/overdue.go:
// Package report produces printable reports for library staff.
package report

import (
	"fmt"
	"sort"
	"strings"

	"example.com/libloans/calendar"
	"example.com/libloans/lending"
	"example.com/libloans/money"
)

// Overdue returns the overdue report as of asOf. (T8)
func Overdue(loans []lending.Loan, asOf calendar.Date) string {
	type row struct {
		loan lending.Loan
		late int
		fine money.Cents
	}
	var rows []row
	for _, l := range loans {
		// DaysBetween counts both ends (T3 as corrected): 1 is the same day.
		if calendar.DaysBetween(l.Borrowed, asOf) < 1 ||
			l.Returned != nil && calendar.DaysBetween(asOf, *l.Returned) <= 1 ||
			calendar.DaysBetween(l.Due, asOf) <= 1 {
			continue
		}
		fine, err := lending.Fine(l.Kind, l.Due, asOf)
		if err != nil {
			continue
		}
		rows = append(rows, row{l, calendar.DaysBetween(l.Due, asOf) - 1, fine})
	}
	sort.Slice(rows, func(i, j int) bool {
		a, b := rows[i], rows[j]
		if a.late != b.late {
			return a.late > b.late
		}
		if a.loan.Patron != b.loan.Patron {
			return a.loan.Patron < b.loan.Patron
		}
		if a.loan.ISBN != b.loan.ISBN {
			return a.loan.ISBN < b.loan.ISBN
		}
		return a.loan.Title < b.loan.Title
	})
	var out strings.Builder
	fmt.Fprintf(&out, "OVERDUE AS OF %s\n", asOf)
	var sum money.Cents
	for _, r := range rows {
		days := "days"
		if r.late == 1 {
			days = "day"
		}
		fmt.Fprintf(&out, "%s\t%s\t%s\tdue %s\t%d %s late\t%s\n",
			r.loan.Patron, r.loan.ISBN, r.loan.Title, r.loan.Due, r.late, days, r.fine)
		sum += r.fine
	}
	items := "items"
	if len(rows) == 1 {
		items = "item"
	}
	fmt.Fprintf(&out, "TOTAL %d %s %s\n", len(rows), items, sum)
	return out.String()
}

reference.report/statement.go:
package report

import (
	"errors"
	"fmt"
	"sort"
	"strings"

	"example.com/libloans/calendar"
	"example.com/libloans/lending"
	"example.com/libloans/money"
)

// ErrUnknownPatron is returned when the patron has no loans to report. (T9)
var ErrUnknownPatron = errors.New("report: unknown patron")

// Statement returns one patron's account as of asOf. (T9)
func Statement(loans []lending.Loan, patron string, asOf calendar.Date) (string, error) {
	type line struct {
		loan lending.Loan
		on   calendar.Date // Due while on loan, Returned once returned
		text string
		fine money.Cents
	}
	var onLoan, returned []line
	counted := false
	for _, l := range loans {
		switch l.Kind {
		case lending.Book, lending.DVD, lending.Magazine:
		default:
			continue
		}
		// DaysBetween counts both ends (T3 as corrected): 1 is the same day.
		if l.Patron != patron || calendar.DaysBetween(l.Borrowed, asOf) < 1 {
			continue
		}
		counted = true
		item := fmt.Sprintf("  %s (%s)", l.Title, l.ISBN)
		if l.Returned == nil || calendar.DaysBetween(asOf, *l.Returned) > 1 {
			text := fmt.Sprintf("%s due %s", item, l.Due)
			var fine money.Cents
			if calendar.DaysBetween(l.Due, asOf) > 1 {
				fine, _ = lending.Fine(l.Kind, l.Due, asOf)
				text += fmt.Sprintf(" OVERDUE %s", fine)
			}
			onLoan = append(onLoan, line{l, l.Due, text, fine})
		} else if calendar.DaysBetween(l.Due, *l.Returned) > 1 {
			fine, _ := lending.Fine(l.Kind, l.Due, *l.Returned)
			text := fmt.Sprintf("%s returned %s fine %s", item, *l.Returned, fine)
			returned = append(returned, line{l, *l.Returned, text, fine})
		}
	}
	if !counted {
		return "", fmt.Errorf("%w: %q", ErrUnknownPatron, patron)
	}
	var out strings.Builder
	fmt.Fprintf(&out, "STATEMENT FOR %s AS OF %s\n", patron, asOf)
	var balance money.Cents
	for i, section := range [][]line{onLoan, returned} {
		out.WriteString([]string{"ON LOAN\n", "RETURNED LATE\n"}[i])
		// YYYY-MM-DD with four-digit years sorts as the dates do.
		sort.Slice(section, func(i, j int) bool {
			a, b := section[i], section[j]
			if a.on != b.on {
				return a.on.String() < b.on.String()
			}
			if a.loan.Title != b.loan.Title {
				return a.loan.Title < b.loan.Title
			}
			return a.loan.ISBN < b.loan.ISBN
		})
		for _, l := range section {
			out.WriteString(l.text + "\n")
			balance += l.fine
		}
		if len(section) == 0 {
			out.WriteString("  none\n")
		}
	}
	fmt.Fprintf(&out, "BALANCE %s\n", balance)
	return out.String(), nil
}

