func (d Date) Weekday() time.Weekday {
	return d.time().Weekday()
}

// DaysBetween returns the signed number of days from from to to. (T3)
func DaysBetween(from, to Date) int {
	// Through String and the time package only, so the body fits any Date's fields.
	a, _ := time.Parse("2006-01-02", from.String())
	b, _ := time.Parse("2006-01-02", to.String())
	return int((b.Unix() - a.Unix()) / 86400)
}

