package report

import (
	"errors"
	"fmt"
	"sort"
	"strings"

	"example.com/libloans/calendar"
	"example.com/libloans/lending"
	"example.com/libloans/money"
)

// ErrUnknownPatron is returned when the patron has no loans to report. (T9)
var ErrUnknownPatron = errors.New("report: unknown patron")

// Statement returns one patron's account as of asOf. (T9)
func Statement(loans []lending.Loan, patron string, asOf calendar.Date) (string, error) {
	type line struct {
		loan lending.Loan
		on   calendar.Date // Due while on loan, Returned once returned
		text string
		fine money.Cents
	}
	var onLoan, returned []line
	counted := false
	for _, l := range loans {
		switch l.Kind {
		case lending.Book, lending.DVD, lending.Magazine:
		default:
			continue
		}
		// DaysBetween is 0 for the same day (T3).
		if l.Patron != patron || calendar.DaysBetween(l.Borrowed, asOf) < 0 {
			continue
		}
		counted = true
		item := fmt.Sprintf("  %s (%s)", l.Title, l.ISBN)
		if l.Returned == nil || calendar.DaysBetween(asOf, *l.Returned) > 0 {
			text := fmt.Sprintf("%s due %s", item, l.Due)
			var fine money.Cents
			if calendar.DaysBetween(l.Due, asOf) > 0 {
				fine, _ = lending.Fine(l.Kind, l.Due, asOf)
				text += fmt.Sprintf(" OVERDUE %s", fine)
			}
			onLoan = append(onLoan, line{l, l.Due, text, fine})
		} else if calendar.DaysBetween(l.Due, *l.Returned) > 0 {
			fine, _ := lending.Fine(l.Kind, l.Due, *l.Returned)
			text := fmt.Sprintf("%s returned %s fine %s", item, *l.Returned, fine)
			returned = append(returned, line{l, *l.Returned, text, fine})
		}
	}
	if !counted {
		return "", fmt.Errorf("%w: %q", ErrUnknownPatron, patron)
	}
	var out strings.Builder
	fmt.Fprintf(&out, "STATEMENT FOR %s AS OF %s\n", patron, asOf)
	var balance money.Cents
	for i, section := range [][]line{onLoan, returned} {
		out.WriteString([]string{"ON LOAN\n", "RETURNED LATE\n"}[i])
		// YYYY-MM-DD with four-digit years sorts as the dates do.
		sort.Slice(section, func(i, j int) bool {
			a, b := section[i], section[j]
			if a.on != b.on {
				return a.on.String() < b.on.String()
			}
			if a.loan.Title != b.loan.Title {
				return a.loan.Title < b.loan.Title
			}
			return a.loan.ISBN < b.loan.ISBN
		})
		for _, l := range section {
			out.WriteString(l.text + "\n")
			balance += l.fine
		}
		if len(section) == 0 {
			out.WriteString("  none\n")
		}
	}
	fmt.Fprintf(&out, "BALANCE %s\n", balance)
	return out.String(), nil
}

