func date(t *testing.T, s string) calendar.Date {
	t.Helper()
	d, err := calendar.Parse(s)
	if err != nil {
		t.Fatalf("Parse(%q): %v", s, err)
	}
	return d
}

func ptr(d calendar.Date) *calendar.Date { return &d }

// T1: money.

func TestMoneyParse(t *testing.T) {
	for s, want := range map[string]money.Cents{
		"0": 0, "7": 700, "12.50": 1250, "007.05": 705, "1.00": 100, "0.01": 1, "000000000": 0,
		"999999999.99": 99999999999, "123456789": 12345678900,
	} {
		if got, err := money.Parse(s); err != nil || got != want {
			t.Errorf("Parse(%q) = %d, %v; want %d, nil", s, int64(got), err, int64(want))
		}
	}
	for _, s := range []string{
		"", " 1", "1 ", "\t1", "-1", "+1", "$1", "1,000", "1.5", "1.505", "1.", ".50", "1234567890",
		"1234567890.00", "1..00", "1.0a", "a", "１", "1e3", "-0.00", "1.-5", ".", "12.50\n",
	} {
		if got, err := money.Parse(s); got != 0 || !errors.Is(err, money.ErrInvalidAmount) {
			t.Errorf("Parse(%q) = %d, %v; want 0, ErrInvalidAmount", s, int64(got), err)
		}
	}
}

