// T7: loan records. TestParseLoanReturnOrder holds the cases that compare the two dates.

func TestParseLoan(t *testing.T) {
	for _, c := range []struct {
		line string
		want lending.Loan
	}{
		{"Ada Lovelace | 0-306-40615-2 | Notes on the Engine | Book | 2026-11-10 |",
			lending.Loan{Patron: "Ada Lovelace", ISBN: "9780306406157", Title: "Notes on the Engine",
				Kind: lending.Book, Borrowed: date(t, "2026-11-10"), Due: date(t, "2026-12-01")}},
		{"Bob Byte|9780000000002|Space Film|DVD|2026-11-08|2026-11-20",
			lending.Loan{Patron: "Bob Byte", ISBN: "9780000000002", Title: "Space Film", Kind: lending.DVD,
				Borrowed: date(t, "2026-11-08"), Due: date(t, "2026-11-16"), Returned: ptr(date(t, "2026-11-20"))}},
		{"  cy  |\t080442957X | Weekly  News |MAGAZINE| 2026-11-01 |  ",
			lending.Loan{Patron: "cy", ISBN: "9780804429573", Title: "Weekly  News", Kind: lending.Magazine,
				Borrowed: date(t, "2026-11-01"), Due: date(t, "2026-11-16")}},
		{"D|978 0 306 40615 7|T|dvd|2026-12-28|2027-03-01",
			lending.Loan{Patron: "D", ISBN: "9780306406157", Title: "T", Kind: lending.DVD,
				Borrowed: date(t, "2026-12-28"), Due: date(t, "2027-01-04"), Returned: ptr(date(t, "2027-03-01"))}},
	} {
		got, err := lending.ParseLoan(c.line)
		same := got.Returned == nil && c.want.Returned == nil ||
			got.Returned != nil && c.want.Returned != nil && *got.Returned == *c.want.Returned
		got.Returned, c.want.Returned = nil, nil
		if err != nil || got != c.want || !same {
			t.Errorf("ParseLoan(%q) = %+v, %v; want %+v", c.line, got, err, c.want)
		}
	}
}

func TestParseLoanErrors(t *testing.T) {
	for _, c := range []struct {
		line string
		want error
	}{
		{"", lending.ErrMalformedLine},
		{"Ada|0306406152|Notes|book|2026-11-10", lending.ErrMalformedLine},
		{"Ada|0306406152|Notes|book|2026-11-10||", lending.ErrMalformedLine},
		{"Ada,0306406152,Notes,book,2026-11-10,", lending.ErrMalformedLine},
		{" |0306406152|Notes|book|2026-11-10|", lending.ErrMalformedLine},
		{"Ada|0306406152|\t|book|2026-11-10|", lending.ErrMalformedLine},
		{"Ada|0306406153|Notes|book|2026-11-10|", isbn.ErrInvalidISBN},
		{"Ada||Notes|book|2026-11-10|", isbn.ErrInvalidISBN},
		{"Ada|0306406152|Notes|cd|2026-11-10|", lending.ErrUnknownKind},
		{"Ada|0306406152|Notes||2026-11-10|", lending.ErrUnknownKind},
		{"Ada|0306406152|Notes|book|2026-11-31|", calendar.ErrInvalidDate},
		{"Ada|0306406152|Notes|book||", calendar.ErrInvalidDate},
		{"Ada|0306406152|Notes|book|2026-11-10|2026/11/20", calendar.ErrInvalidDate},
		{"Ada|0306406152|Notes|book|2026-11-10|2026-11-20T10:00", calendar.ErrInvalidDate},
	} {
		got, err := lending.ParseLoan(c.line)
		if got != (lending.Loan{}) || !errors.Is(err, c.want) {
			t.Errorf("ParseLoan(%q) = %+v, %v; want zero, %v", c.line, got, err, c.want)
		}
	}
}

func TestParseLoanReturnOrder(t *testing.T) {
	for _, c := range []struct {
		borrowed, returned string
		ok                 bool
	}{
		{"2026-11-10", "2026-11-10", true}, {"2026-11-10", "2026-11-09", false}, {"2026-11-10", "2026-11-11", true},
		{"2026-11-10", "2026-10-11", false}, {"2026-12-31", "2026-12-30", false}, {"2026-12-31", "2027-01-01", true},
		{"2026-12-31", "2026-12-31", true},
	} {
		line := "Ada Lovelace|0306406152|Notes on the Engine|book|" + c.borrowed + "|" + c.returned
		got, err := lending.ParseLoan(line)
		if c.ok && (err != nil || got.Returned == nil || *got.Returned != date(t, c.returned)) {
			t.Errorf("ParseLoan(%q) = %+v, %v; want returned %s", line, got, err, c.returned)
		}
		if !c.ok && (got != (lending.Loan{}) || !errors.Is(err, lending.ErrMalformedLine)) {
			t.Errorf("ParseLoan(%q) = %+v, %v; want zero, ErrMalformedLine", line, got, err)
		}
	}
}

// T8: the overdue report. Every case in TestOverdueReport reads how many days late a loan is,
// or whether it is past due, borrowed or returned as of the day.

func entry(t *testing.T, patron, id, title string, kind lending.ItemKind, borrowed, due, returned string) lending.Loan {
	l := lending.Loan{Patron: patron, ISBN: isbn.ISBN(id), Title: title, Kind: kind,
		Borrowed: date(t, borrowed), Due: date(t, due)}
	if returned != "" {
		l.Returned = ptr(date(t, returned))
	}
	return l
}

func TestOverdueReport(t *testing.T) {
	ada := entry(t, "Ada Lovelace", "9780306406157", "Notes on the Engine", lending.Book, "2026-10-12", "2026-11-02", "")
