	for _, c := range []struct {
		name  string
		loans []lending.Loan
		want  string
	}{
		{"the spec's example", []lending.Loan{bob, ada},
			"OVERDUE AS OF 2026-11-10\nAda Lovelace\t9780306406157\tNotes on the Engine\tdue 2026-11-02\t8 days late\t$2.00\n" +
				"Bob Byte\t9780000000002\tSpace Film\tdue 2026-11-09\t1 day late\t$1.00\nTOTAL 2 items $3.00\n"},
		{"due today is not overdue", []lending.Loan{
			entry(t, "Cy", "9780000000002", "A", lending.Book, "2026-10-20", "2026-11-10", ""), bob},
			"OVERDUE AS OF 2026-11-10\nBob Byte\t9780000000002\tSpace Film\tdue 2026-11-09\t1 day late\t$1.00\nTOTAL 1 item $1.00\n"},
