			"OVERDUE AS OF 2026-11-10\nEve\t9780000000002\tC\tdue 2026-11-09\t1 day late\t$0.10\nTOTAL 1 item $0.10\n"},
		{"borrowed today counts, borrowed later does not", []lending.Loan{
			entry(t, "Cy", "9780000000002", "A", lending.Book, "2026-11-10", "2026-11-05", ""),
			entry(t, "Dee", "9780000000002", "B", lending.Book, "2026-11-11", "2026-11-05", "")},
			"OVERDUE AS OF 2026-11-10\nCy\t9780000000002\tA\tdue 2026-11-05\t5 days late\t$1.25\nTOTAL 1 item $1.25\n"},
