			entry(t, "Ann", "9780306406157", "Mag", lending.Magazine, "2026-09-01", "2026-09-15", ""),
			entry(t, "Ann", "9780000000002", "Mag", lending.Magazine, "2026-09-01", "2026-09-15", ""),
