			entry(t, "Bo", "9780000000002", "Bad kind", 0, "2026-09-01", "2026-09-08", ""),
			entry(t, "Bo", "9780000000002", "Bad kind", 4, "2026-09-01", "2026-09-08", ""),
			entry(t, "Cal", "9780000000002", "Late book", lending.Book, "2026-01-01", "2026-01-22", "")},
			"OVERDUE AS OF 2026-11-10\n" +
				"Cal\t9780000000002\tLate book\tdue 2026-01-22\t292 days late\t$10.00\n" +
				"Zed\t9780000000002\tFilm\tdue 2026-09-08\t63 days late\t$15.00\n" +
				"Ann\t9780000000002\tBook\tdue 2026-09-15\t56 days late\t$10.00\n" +
				"Ann\t9780000000002\tMag\tdue 2026-09-15\t56 days late\t$3.00\n" +
				"Ann\t9780306406157\tMag\tdue 2026-09-15\t56 days late\t$3.00\n" +
				"TOTAL 5 items $41.00\n"},
		{"fines below the cap", []lending.Loan{
